// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { AspectRatio } from "@/registry/erbium/ui/aspect-ratio";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { AspectRatio } from \"@/registry/erbium/ui/aspect-ratio\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof AspectRatio>) => (\n  <AspectRatio\n    {...args}\n    className={`w-80 overflow-hidden rounded-md bg-muted ${args.className ?? \"\"}`}\n  >\n    <div className=\"flex size-full items-center justify-center\">Content at {args.ratio}:1</div>\n  </AspectRatio>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/aspect-ratio-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import SquareExample from "./variants/square";

const SquareSource = "import { AspectRatio } from \"@/registry/erbium/ui/aspect-ratio\";\n\nconst Example = () => (\n  <div className=\"w-60\">\n    <AspectRatio ratio={1}>\n      <div className=\"flex size-full items-center justify-center rounded-lg bg-muted\">\n        Square 1:1\n      </div>\n    </AspectRatio>\n  </div>\n);\n\nexport default Example;\n";

import PortraitExample from "./variants/portrait";

const PortraitSource = "import { AspectRatio } from \"@/registry/erbium/ui/aspect-ratio\";\n\nconst Example = () => (\n  <div className=\"w-40\">\n    <AspectRatio ratio={9 / 16}>\n      <div className=\"flex size-full items-center justify-center rounded-lg bg-muted\">\n        Portrait 9:16\n      </div>\n    </AspectRatio>\n  </div>\n);\n\nexport default Example;\n";

const meta = {
  component: AspectRatio,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "Keeps content at a fixed aspect ratio.\n\n**Import:** `@/registry/erbium/ui/aspect-ratio`\n\n## Usage\n\n```tsx\nimport { AspectRatio } from \"@/registry/erbium/ui/aspect-ratio\";\n```\n\n```tsx\n<AspectRatio ratio={16 / 9}>\n  <Image src=\"...\" alt=\"Image\" className=\"rounded-md object-cover\" />\n</AspectRatio>\n```",
      },
    },
  },
} satisfies Meta<typeof AspectRatio>;

export default { ...meta, title: "Components/Aspect Ratio",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof AspectRatio> = {
  args: { ratio: 16 / 9, className: "" },
  argTypes: { ratio: { control: { type: "number", min: 0.25, max: 4, step: 0.25 } } },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Square: Story = {
  parameters: {
    docs: {
      description: { story: "A square aspect ratio component using the `ratio={1 / 1}` prop. This is useful for displaying images in a square format." },
      source: { code: SquareSource },
    },
  },
  render: SquareExample,
};

export const Portrait: Story = {
  parameters: {
    docs: {
      description: { story: "A portrait aspect ratio component using the `ratio={9 / 16}` prop. This is useful for displaying images in a portrait format." },
      source: { code: PortraitSource },
    },
  },
  render: PortraitExample,
};

import { AspectRatio } from "@/registry/erbium/ui/aspect-ratio";
export default function Demo() {
  return (
    <div className="w-80">
      <AspectRatio ratio={16 / 9}>
        <div className="flex size-full items-center justify-center rounded-lg bg-muted">
          16:9 media area
        </div>
      </AspectRatio>
    </div>
  );
}

import Demo from "../examples/aspect-ratio-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;

import { AspectRatio } from "@/registry/erbium/ui/aspect-ratio";
import type * as React from "react";

const Example = (args: React.ComponentProps<typeof AspectRatio>) => (
  <AspectRatio
    {...args}
    className={`w-80 overflow-hidden rounded-md bg-muted ${args.className ?? ""}`}
  >
    <div className="flex size-full items-center justify-center">Content at {args.ratio}:1</div>
  </AspectRatio>
);

export default Example;

import { AspectRatio } from "@/registry/erbium/ui/aspect-ratio";

const Example = () => (
  <div className="w-40">
    <AspectRatio ratio={9 / 16}>
      <div className="flex size-full items-center justify-center rounded-lg bg-muted">
        Portrait 9:16
      </div>
    </AspectRatio>
  </div>
);

export default Example;

import { AspectRatio } from "@/registry/erbium/ui/aspect-ratio";

const Example = () => (
  <div className="w-60">
    <AspectRatio ratio={1}>
      <div className="flex size-full items-center justify-center rounded-lg bg-muted">
        Square 1:1
      </div>
    </AspectRatio>
  </div>
);

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}
